* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * **			                  **      A P P L E   I I g s   I N S T A L L E R   P R O G R A M   V  2 . 1     **                                                                             **                              by "Jay" Schaffer                              **                               and  Ron Lichty                               **			                  **  Copyright Apple Computer, Inc. 1987-1992              All Rights Reserved  **			                  ** * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *** NOTE:  External routines, which may be located in another bank, must be sure*        they set the proper bank register values or use long addressing as*        needed.**        Code in Startup.asm calls the following external routines:**	AddScripts	- From Subroutines.asm*	Allocate	- From MainSub.asm*	Alphabetize	- From Subroutines.asm*	BuildScriptList	- From Seg 'BuildList' in Startup.asm*	Check4Scripts	- From Subroutines.asm*	CheckMsgCenter	- From Subroutines.asm*	CloseMsgWindow	- From MainSub.asm*	DeRef	- From MainSub.asm*	Error	- From MainSub.asm*	OpenMsgWindow	- From MainSub.asm*	ResizeAppDirBuf	- From MainSub.asm*	UnlockAppDirHdl	- From MainSub.asm*	UnlockCurDirHdl	- From MainSub.asm** * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	Print Push	Print Off	Include 'Installer.Equates'	Print Pop	Seg 'StartUp'	SegAttr Dynamic* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *ToolStartup	Proc Export** Description:	Starts up tools needed for the Installer program and*	creates the system menu bar.** Inputs:	none** Outputs:	none** External Refs:	Import AllDone	Import AlmostAllDone	Import CautionIconPtr	; from Data.asm	Import CurDirStart	Import CurVolStart	Import CurrentVolBuf	Import Dereference	Import Dir2Update	Import Dir2Width	Import Disk2Update	Import Disk2Width	Import GotSCSICard	Import GStrDispose	Import GStrNew	Import GStrResize	Import GStrToGStr	Import Line1	Import Line2	Import MoreDone	Import MyID	Import MyToolID	Import MyZP	Import LaunchVolStrBuffer	Import OKStrText	Import PrefixPointer	Import Prefix9Pointer	Import Preferences	Import ProgramVersion	Import ResizeAppDirBuf	Import ResizeCurDirBuf	Import SavePrefix0	Import SavePrefix9	Import startStopRecRefRet	Import StopIconPtr		; from Data.asm	Import SysDeath	Import SysPrefParms	Import UnlockCurDirHdl	Import UnlockAppDirHdl	Import VolStr	Import VolStrBuffer	Import VolSubstArray	Import wVersion** Entry Points:	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	Eject; Set the data bank to the current code bank	phb	phk	plb; Save the address of our zero page	tdc	sta >MyZP; Startup the Tool Locator and Memory Manager	ldx #TLStartup	jsl ToolLocator	bcc ContinueSysDeath1	jml SysDeathContinue	pha	; Room for result	ldx #MMStartup	jsl ToolLocator	bcs SysDeath1	pla	ora #$0100	; (So we can do a dispose all on every-	sta >MyID	;   thing we allocate before we exit.)	ora #$0200	; (So memory allocated by tools in my	sta >MyToolID	;   name is easily identifiable.); Verify that we are running under the appropriate GS/OS version	jsl GSOS	dc.w Get_Version	dc.l VersionParms	lda VersionParms+2	and #%0111111111111111 ; Mask off "prototype" bit	cmp #$0400	; Version 4.0 minimum because of	bcs SetSystemPref	;  Installer's use of resources & Format call.	jsr Requires6_0	; put text dialog: requires 6.0jMoreDone	plb	jml MoreDone	; jump to shutdown code;         Mini-subroutine:;         We're not running under the required minimum version of GS/OS!;         Notify the user and terminate.Requires6_0	pha	; Space for result	pea Line1>>16	; Pointer to first line of text	pea |Line1	pea Line2>>16	; Pointer to second line of text	pea |Line2	pea Button1>>16	; Pointer to button 1 text (not used)	pea |Button1	pea OKStrText>>16	; Pointer to button 2 text (OK) 	pea |OKStrText	;  (this is button 2, but spaces right-justify it!)	ldx #TLTextMountVolume	jsl ToolLocator	pla	; Ignore result	rts; We're running under GS/OS.  Get the current system preferences and save them.; Then set the flag that instructs GS/OS to display the mount volume dialog;   and to put up both OK and Cancel buttons.SetSystemPref	jsl GSOS	dc.w Get_Sys_Pref	dc.l SysPrefParms	lda >SysPrefParms+2	sta >Preferences	; save for restoration later	lda #%1000000000000000 ; use mount dialog	sta >SysPrefParms+2; Get the present system prefix and save it for later restoration.	pha	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	tax	; Preserve error code	pla	sta >PrefixPointer	pla	sta >PrefixPointer+2	txa	; Restore error code	bcs jMoreDone	; jump to shutdown code	jsl GSOS	; set new system prefs w mount dialog	dc.w Set_Sys_Pref	dc.l SysPrefParms@GetPrefix	jsl GSOS	; Put the prefix in it	dc.w Get_Prefix	dc.l SavePrefix0	pha	; Space for result	pha	lda >PrefixPointer+2 ; Resize the buffer for perfect fit	pha	lda >PrefixPointer	pha	jsl GStrResize	pla	sta >PrefixPointer	pla	sta >PrefixPointer+2	bcs @GetPrefix	; Try again if we didn't get it all	pha	; Space for result	pha	lda >PrefixPointer+2 ; Get the handle	pha	lda >PrefixPointer	pha	ldx #FindHandle	jsl ToolLocator	pla	; Ignore errors	sta <PrefixHandle	pla	sta <PrefixHandle+2		pha	pei <PrefixHandle	ldx #HUnlock	; Let the buffer float til needed again	jsl ToolLocator; Clear prefix zero so that GS/OS will be forced to use prefix eight which can; handle lÑoÑnÑg prefixes.	jsl GSOS	dc.w Set_Prefix	dc.l PrefixParms; Put the version information in the 'About Installer...' dialog	sep #$0030	LongA Off	LongI Off	lda >wVersion	tax@VersionLoop	lda >wVersion,x	sta >ProgramVersion-1,x	dex	bne @VersionLoop	; (don't move length byte)	LongI On	LongA On	rep #$0030; Load and initialize the tools we'll need	pha	; Space for result	pha	lda >MyToolID	pha	; userID = MyToolID	pea $0002	; startStopDesc = resource	pea $0000	; startStopRecRef = rToolStartup ID=1	pea $0001	ldx #StartUpTools	jsl ToolLocator	pla	sta >startStopRecRefRet	pla	sta >startStopRecRefRet+2	bcc @noStartToolErr	; continue if no error	jsr Requires6_0	; if error, not booted from Sys 6.0	plb	jml AlmostAllDone	; jump to shutdown code but no shutdown!@noStartToolErr; We now have a desktop with a blank menu bar.  Well need a real Apple Logo; Menu for New Desk Accessories and 'About Installer...' and File and Edit; to support desk accessories.	pha	; Space for result	pha	pea $0002	; refDescriptor - resource	pea $0000	; menuBarTRef - rMenuBar ID=1	pea $0001	pea $0000	; windowPtr - nill=system menu bar	pea $0000	ldx #NewMenuBar2	jsl ToolLocator		; Leave Menu's handle on stack	ldx #SetSysBar	jsl ToolLocator	pea $0000	; barHandle - nil=system menu bar	pea $0000	ldx #SetMenuBar	jsl ToolLocator	pea $0001	; Call the Desk Accessory Manager to	ldx #FixAppleMenu	;  install the list	of NDAs	jsl ToolLocator	pha	; Room for returned	bar height	ldx #FixMenuBar	; Initialize menu bar/menus sizes	jsl ToolLocator	pla	; Discard result (generally of no use)	ldx #DrawMenuBar	; Draw the menu bar	and menu titles	jsl ToolLocator; Get the launch volume.	pha	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer: temporary	tax	; Preserve error code	pla	sta >Prefix9Pointer	pla	sta >Prefix9Pointer+2	txa	; Restore error code	bcs bcsjAllDone	; jump to shutdown code bcs puddle-jump@GetPrefix9	jsl GSOS	; Put the prefix in it	dc.w Get_Prefix	dc.l SavePrefix9	pha	; Space for result	pha	lda >Prefix9Pointer+2 ; Resize the buffer for perfect fit	pha	lda >Prefix9Pointer	pha	jsl GStrResize	pla	sta >Prefix9Pointer	pla	sta >Prefix9Pointer+2	bcs @GetPrefix9	; Try again if we didn't get it all	lda >Prefix9Pointer+2	tax	phx	lda >Prefix9Pointer	pha	phx	; second set for GStrToGStr source	pha	phx	; third set for GStrDispose	pha	jsr GStrJustVolume	; reduce to just volume, not whole prefix	pea LaunchVolStrBuffer>>16 ; (Prefix9Pointer alr on stack)	pea |LaunchVolStrBuffer	jsl GStrToGStr	; copy just volume, not whole prefix	jsl GStrDispose	; dispose of prefix memory (Prefix9Pointer alr on stack); Initialize "Everything" to be the boot volumeÑÑCurDir, CurrentVol, and; ApplicationDir.GetBootVol	jsl GSOS	; Get the boot volume name into	dc.w Get_Boot_Vol	;   VolStrBuffer / VolStr	dc.l GetBootVolParms;       Copy boot volume name into AppDirectory (with trailing separator char)	pha	; Initialize Application Directory	pha	; Space for result	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	plx	stx <AppDirPtr	plx	stx <AppDirPtr+2bcsjAllDone	bcs jAllDone	; jump to shutdown code	pea VolStrBuffer>>16 ;Put a copy into AppDirectory	pea |VolStrBuffer	pei <AppDirPtr+2	pei <AppDirPtr	jsl GStrToGStr	jsl ResizeAppDirBuf;       Copy boot volume name into CurDirectory.	pha	; Space for result	pha	pea 0000	; (use GStr's default length)	lda >MyID	pha	jsl GStrNew	; Get a new, locked buffer	plx	stx <CurDirPtr	plx	stx <CurDirPtr+2	bcc CopyTheStringjAllDone	plb	jml AllDone	; jump to shutdown codeCopyTheString	pea VolStrBuffer>>16 ;Put a copy into CurDirectory	pea |VolStrBuffer	pei <CurDirPtr+2	pei <CurDirPtr	jsl GStrToGStr	jsl ResizeCurDirBuf;       Copy boot volume name into CurrentVol.;       Get_Boot_Vol returns the volume name with a trailing separator char.;       We don't want one on CurrentVol, so delete it by decrementing ;       the string length.	lda >VolStr	dec a	sta >VolStr	pea VolStrBuffer>>16 ;Put a copy into CurrentVol	pea |VolStrBuffer	pea CurrentVolBuf>>16	pea |CurrentVolBuf	jsl GStrToGStr;       Set CurrentVol as the substitution string for Easy UpdateÕs message.	pea VolSubstArray>>16	pea |VolSubstArray	ldx #SetCtlParamPtr	jsl ToolLocator;       Store the handles to CurDirectory and AppDirectory and let them float;       until they're needed again.	pha	; Get the handle	pha	pei <CurDirPtr+2	pei <CurDirPtr	ldx #FindHandle	jsl ToolLocator	pla	; Ignore errors	sta <CurDirHdl	pla	sta <CurDirHdl+2	pha	; Get the handle	pha	pei <AppDirPtr+2	pei <AppDirPtr	ldx #FindHandle	jsl ToolLocator	pla	; Ignore errors	sta <AppDirHdl	pla	sta <AppDirHdl+2	jsl UnlockCurDirHdl	; Let it float til needed	jsl UnlockAppDirHdl; Find out how much room we need for the Disk/Volume to update text and fix the; rectangle definitions.	pha	; Room for result	pea Disk2Update>>16	; String pointer	pea |Disk2Update	ldx #StringWidth	jsl ToolLocator	clc	pla	; Get the width	adc #0018	; Add 18 to the width...	sta >Disk2Width	;  ...and store the result	sta >CurVolStart	;  ...and set start of volume name	pha	; Room for result	pea Dir2Update>>16	; String pointer	pea |Dir2Update	ldx #StringWidth	jsl ToolLocator	clc	pla	; Get the width	adc #0018	; Add 18 to the width...	sta >Dir2Width	;  ...and store the result	sta >CurDirStart	;  ...and set start of directory name; Check to see if a SCSI card is present (for Missing Disk? menu item & Easy Update use)	lda #0	sta >GotSCSICard	; initialize: noneSlotROM	equ $00E0C000ID1	equ $05	; Must = $00ID2	equ $07	; Must = $03ID3	equ $0B	; Must = SCSICard ir hsSCSICardSCSICard	equ $08D8	; ID word for original S.C.S.I. cardhsSCSICard	equ $0570	; ID word for hi-speed S.C.S.I. card;       Initialize the slot pointer to non-existent peripheral slot zero.	lda #<SlotROM	sta <ZPTemp2	lda #^SlotROM	sta <ZPTemp2+2;       Advance the slot pointer to the next slot and check to see if we've;       done all seven slots yet.SCSILoop	clc	; Set up for next slot	lda <ZPTemp2	adc #$0100	sta <ZPTemp2	tax	lda <ZPTemp2+2	adc #$0000	sta <ZPTemp2+2	cpx #$C800	; Have we checked all the slots?	beq NoSCSI	; If so, we're finished looking!	ldy #ID1	; First two ID bytes are the same for	lda [<ZPTemp2],y	;  either S.C.S.I. card.	and #$00FF	; (only checking bytes)	cmp #$0003	; If 1st ID byte ­ $03, next slot	bne SCSILoop	ldy #ID2	lda [<ZPTemp2],y	and #$00FF	; (only checking bytes)	bne SCSILoop	; If 2nd ID byte ­ $00, next slot	ldy #ID3	lda [<ZPTemp2],y	cmp #SCSICard	; Check for original S.C.S.I. card	beq FoundSCSICard	cmp #hsSCSICard	; Check for high speed S.C.S.I. card	bne SCSILoop;       Found a S.C.S.I. card.  The presence of this card is assumed to;       indicate the existence of a S.C.S.I. hard disk.  Add the driver.FoundSCSICard	lda #$FFFF	sta >GotSCSICardNoSCSI; Get handle to Stop Sign resource and save for dialogs.	pha	; space for result	pha	pea rIcon	pea rIconStopID>>16	pea |rIconStopID	ldx #LoadResource	jsl ToolLocator	; handle of resource left on stack	jsl DeReference	pla	; pointer to resource	sta >StopIconPtr	pla	sta >StopIconPtr+2; Get handle to Caution Sign resource and save for dialogs.	pha	; space for result	pha	pea rIcon	pea rIconCautionID>>16	pea |rIconCautionID	ldx #LoadResource	jsl ToolLocator	; handle of resource left on stack	jsl DeReference	pla	; pointer to resource	sta >CautionIconPtr	pla	sta >CautionIconPtr+2	plb	rtl	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *GStrJustVolume	; (local)** Description:	Resets the length of a GStr to just the volume length*	(without trailing separator).** Inputs:	Pointer to GStr** Outputs:	none** Errors:	none** External Refs:	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; stack -> direct page frameStrLen	equ $01	; Local varRtnAddr	equ StrLen+2	; Subroutine return addressSrc	equ RtnAddr+2	; Pointer to GStringVariables	equ Src	; Bytes of variables; Provide space for local variable and make stack our D-page.	pha	; 2 bytes of local variables	tsc	phd	tcd; Get length; check for a null string.	ldy #2	; length word	lda [Src],y	beq JustFinished	; branch if string is null	inc a	; transform to value to compare with	inc a	inc a	inc a	sta StrLen	; value to compare with; Walk the string past initial separator char	ldy #5	; 2nd char: 1st char past leading colonJustLoop	lda [Src],y	and #$00FF	; look at just first char	cmp #SeparatorChar	beq VolumeEnd	iny	cpy StrLen	bcc JustLoop	bra JustFinished	; no trailing colon: leave length alone; found end of volume name; store new lengthVolumeEnd	dey	; subtract 4 (don't count trailing separator char)	dey	dey	dey	tya	ldy #2	; length word	sta [Src],y; Restore the environmentJustFinished	pld	; Restore D-page	pla	; Remove local var	pla	; Move return address...	sta 3,s	;  ...past 4 bytes of inputs	pla	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .PrefixParms	dc.w 0002	; pCountPrefixNumber	dc.w 0000	; Prefix numberPrefixPath	dc.l PrefixNumber	; Prefix pathname (null string)Button1	dc.b 00	; Button 1 is not usedVersionParms	dc.w 0001	; pCount	ds.w 1	; GS/OS Version numberGetBootVolParms	dc.w 0001	; pCountGetBootVolBufPtr	dc.l VolStrBuffer	; data buffer pointer	EndP	Eject	Seg 'Standard'	SegAttr Dynamic* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *StandardDialog	Proc Export** Description:	Creates the Standard Update dialog window.** Inputs:	none** Outputs:	none** External Refs:	Import StandardDrawProc	Import StandardHdlTable	Import StandardPort	Import wTitleStd** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phb	phk	plb; Open the Standard Update window and install all controls.	pha	; Space for result	pha	pea wTitleStd>>16	; titlePtr	pea |wTitleStd	pea 0000	; refCon	pea 0000	pea StandardDrawProc>>16 ; contentDrawPtr	pea |StandardDrawProc	pea 0000	; defProcPtr	pea 0000	pea 0002	; paramTableDesc (2=resource)	pea 0000	; paramTableRef (resourceID)	pea 0002	pea rWindParam1	ldx #NewWindow2	jsl ToolLocator	plx	; Get window's grafPortPtr	ply	bcs @Done	txa	sta >StandardPort	tya	sta >StandardPort+2;;;	phy	; #####################################;;;	phx	; ### Does this cause the controls  ###;;;	ldx #DrawControls	; ### to be drawn twice on startup? ###;;;	jsl ToolLocator	; #####################################; Get the handles for all the controls that we will want to enable/disable; and store them for ready access.	lda #0001	; Initialize loop counter	sta Temp@HandleLoop	pha	; Space for result	pha	lda >StandardPort+2	; windowPtr	pha	lda >StandardPort	pha	pea 0000	; ctrlID	lda Temp	pha	ldx #GetCtlHandleFromID	jsl ToolLocator	bcs @done	lda Temp	asl a	asl a	tax	pla	; Begin storing at the "zero-th"	sta >StandardHdlTable-4,x ; location, not the first.	inx	inx	pla	sta >StandardHdlTable-4,x	inc Temp	bra @HandleLoop@Done	pla	; Clean up the stack	pla	plb	lda #0000	clc	rtlTemp	ds.w 1	EndP	Eject	Seg 'Custom'	SegAttr Dynamic* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CustomDialog	ProcName Export** Description:	Creates the customized installation dialog window*	and builds the script list if necessary.** Inputs:	none** Outputs:	cFlag clear: no errors*	cFlag set: error - a-Reg contains error code** External Refs:	Import AllDone	Import BuildScriptList	Import C1InpToPStr	Import CurrentVol	Import CustomDrawProc	Import DeRef	Import DialogPort	Import Error	Import GStrNew;;;	Import GStrToPStr	Import GStrResize	Import HandleTable	Import MenuItemName	Import MyPopUpCtlHdl	Import MyPopUpCtlHdl	Import PointerSize	Import ScriptListBarHdl	Import ScriptListCtlHdl	Import ScriptListFlag	Import ScriptListSize	Import SelectListBarHdl	Import SelectListCtlHdl	Import StandardNo	Import StandardUpdateHdl	Import wTitleCustom** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phb	phk	plb; If we haven't built a script list yet, do it now, otherwise, go on.	lda >ScriptListFlag	bmi @0	jsl BuildScriptList	php	; Save cFlag	pha	; Save error code, if any	pha	; Unload 'BuildList' segment	pha	; 6-bytes for results	pha	pea BuildScriptList>>16	pea |BuildScriptList	ldx #UnloadSeg	jsl ToolLocator	pla	; discard UserID	pla	; discard loadFileNum	pla	; discard loadSegNum	pla	; Restore error code, if any	plp	; Restore cFlag	bcc @00@jCustomExit	brl CustomExit@00	lda #$8000	; Indicate that the script list is	sta >ScriptListFlag	;   now built!@0; Every time we switch to the Customize window, we must reconnect the script list control.; We found some scripts.  Fix the ListControl resource template to point to the fixed; ListRecord in the 'Main' segment, so when the control is created it will too.	pha	; Load the ListControl resource into memory	pha	; space for result	pea rControlTemplate ;resource type	pea 0000	; resource ID	pea ScriptListCtl	ldx #LoadResource	jsl ToolLocator	sta Temp	; Save error code	pla	; Lock and dereference the handle	plx	ldy Temp	; Restore error code	beq SkipError	jsl Error	bra @jCustomExitSkipError	phx	; save the control resource's handle	pha	pea 0000	; set purge level to 0: not purgeable	phx	; control resource's handle	pha	;  (we want it to be around when control is created	ldx #SetPurge	jsl ToolLocator	pla	; Lock & dereference the control resource's handle	plx	jsl DeRef	sta <ZPTemp	stx <ZPTemp+2	ldy #rListRef	; Update the ListRecord pointer.	lda <ScriptListPtr	; script list pointer	sta [<ZPTemp],y	; into the resource	iny	iny	lda <ScriptListPtr+2	sta [<ZPTemp],y	ldy #rListSize	; Update the ListSize value.	lda >ScriptListSize	; script list size	sta [<ZPTemp],y; Determine which Item(s) are selected and always be sure that if one or more; items are selected, that the first selected item appears as the first item; in the display.  (We have to do this manually!  The list control has not been; installed yet, so we have no handle to make a call to the list manager.)	ldx #0000	; Initialize item counter	ldy #0000	; Initialize indexSelectionSearchLoop	inx	; Next item	iny	; Position on the flags	iny	iny	iny	lda [<ScriptListPtr],y	iny	; Position on next entry	iny	and #$0080	; Look at the selection bit	bne MarkListStart	tya	cmp >PointerSize	bcc SelectionSearchLoop	ldx #0001	; Start at first item if nothing selectedMarkListStart	ldy #rListStart	txa	sta [<ZPTemp],y; Open a Window for	use as a pseudo Dialog Box and install all controls.; Substitute our fixed 'ContDefProc' in segment 'Main' in place of the null; pointer in the resource.	pha	; Space for result	pha	pea wTitleCustom>>16 ; titlePtr	pea |wTitleCustom	pea 0000	; refCon	pea 0000	pea CustomDrawProc>>16 ; contentDrawPtr	pea |CustomDrawProc	pea 0000	; defProcPtr	pea 0000	pea 0002	; paramTableDesc (2=resource)	pea 0000	; paramTableRef (resourceID)	pea 0001	pea rWindParam1	ldx #NewWindow2	jsl ToolLocator	plx	; Get window's grafPortPtr	ply	bcc @1	plb	jml AllDone	; jump to shutdown code@1	txa	sta >DialogPort	tya	sta >DialogPort+2	phy	phx	ldx #SetPort	jsl ToolLocator; Get the handles for all the controls that we will want to enable/disable; and store them for ready access.	lda #0001	; Initialize loop counter	sta Temp@HandleLoop	pha	; Space for result	pha	lda >DialogPort+2	; windowPtr	pha	lda >DialogPort	pha	pea 0000	; ctrlID	lda Temp	pha	ldx #GetCtlHandleFromID	jsl ToolLocator	bcs @done	lda Temp	asl a	asl a	tax	pla	; Begin storing at the "zero-th"	sta >HandleTable-4,x ; location, not the first.	inx	inx	pla	sta >HandleTable-4,x	inc Temp	bra @HandleLoop@Done	pla	; Clean up the stack	pla; Gotta get the list window scroll bars separately since we didn't create them; or give them a ctlID	lda >ScriptListCtlHdl+2	tax	lda >ScriptListCtlHdl	jsl DeRef	sta <ZPTemp	stx <ZPTemp+2	ldy #$0034	; Offset to ctlListBar	lda [<ZPTemp],y	sta >ScriptListBarHdl	iny	iny	lda [<ZPTemp],Y	sta >ScriptListBarHdl+2	lda >SelectListCtlHdl+2	tax	lda >SelectListCtlHdl	jsl DeRef	sta <ZPTemp	stx <ZPTemp+2	ldy #$0034	; Offset to ctlListBar	lda [<ZPTemp],y	sta >SelectListBarHdl	iny	iny	lda [<ZPTemp],Y	sta >SelectListBarHdl+2	clc	; return ÔokÕ to caller; Perform a few remaining miscellaneous chores and we'll be all setup.;     Check StandardNo; if set, hide Standard Update button	lda >StandardNo	beq CustomExit	lda >StandardUpdateHdl+2	pha	lda >StandardUpdateHdl	pha	ldx #HideControl	jsl ToolLocatorCustomExit	plb	rtl; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .Temp	ds.w 1	EndP	Eject	Seg 'BuildList'	SegAttr Dynamic* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *BuildScriptList	Proc** Description:	Called once to build a list of all scripts found in the*	SCRIPTS folder and the root directory of each on-line*	volume.  It checks the memory whose handle is stored in*	"MessageCenterHdl" and adds them to the list if needed*	with them hilited.** Inputs:	none** Outputs:	cFlag clear: no errors*	cFlag set: error - a-Reg contains error code** External Refs:	Import AddScripts	Import Allocate	Import Alphabetize	Import Check4Scripts	Import CheckMsgCenter	Import CloseMsgWindow	Import D_DeviceNum	Import D_Info_Parms	Import DeRef	Import Dev_Name	Import Error	Import GStrDispose	Import GStrNew	Import GStrResize	Import MyID	Import OpenMsgWindow	Import PointerSize	Import ScriptFileHdl	Import ScriptListHdl	Import ScriptListSize	Import StandBy** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phb	phk	plb; Check to see if we can find any scripts, and quit if we can't.  (This; subroutine creates the lists for the list manager in the 'main' segment.);       Get a null block of memory to put ScripName info in	lda #0000	; Size of block to create	jsl Allocate	txa	sta >ScriptListHdl	tya	sta >ScriptListHdl+2;       Get a null block of memory to put Script filename info in	lda #0000	; Size of block to create	jsl Allocate	txa	sta >ScriptFileHdl	tya	sta >ScriptFileHdl+2	jsr FindScripts	bcs ReportError	; Did an error occur?	lda >ScriptListSize	; Did we find any scripts?	bne SkipAllDone	lda #$0082	; If no scripts were found, let user knowReportError	jsl Error	; Notify user of errors	bra BuildListExitSkipAllDone	clc	; no errorBuildListExit	plb	rtl	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .FindScripts;	Script List:;	A local subroutine to find ALL online scripts by;	calling AddScripts to get everything in the SCRIPTS;	folder and then repeatedly calling AddScripts while;	passing the names of all directories that can legally;	contain script files.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; This may take a while, so put up a notification for the user.	ldx #StandBy	ldy #^StandBy	jsl OpenMsgWindow; get a buffer to use for pathnames	pha	; Room for result	pha	pea 0000	; Size	lda >MyID	pha	; ID	jsl GStrNew	plx	stx outputPath	pla	sta outputPath+2; Get the handle to the buffer, since the pointer may change in jsl AddScripts	pha	pha	pha	; GStr to get handle to	phx	ldx #FindHandle	jsl ToolLocator	plx	; A-reg contains error code: should be none	ply	stx outputPathHdl	sty outputPathHdl+2; Expand the name "9:SCRIPTS" and check there.	jsl GSOS	dc.w Expand_Path	dc.l Expand_Parms	pha	; Room for result	pha	lda outputPath+2	; Pointer to GStr to resize	pha	lda outputPath	; NOTE: GStrNew creates a 1K buffer.	pha	;       the full pathname is	jsl GStrResize	;       assumed to always be smaller!	plx	; new pointer to GStr	ply; Check for scripts in the SCRIPTS folder.  Ignore any errors.  (We still may; find other scripts whether this folder exists or not or we got some other; error.); Pass pointer to GStr in x/y.	jsl AddScripts	; rdl: 5/23/91 replace Check4Scripts	ldx outputPathHdl+2	; Reestablish the ptr in outputPath	lda outputPathHdl	;   (AddScripts may have moved it)	jsl DeRef	sta outputPath	stx outputPath+2	Eject; Now start with device #1 and check the root directories of all volumes.	lda >D_DeviceNum	; Save the current device number	sta Temp	lda #0000	; Set current device to zero	sta >D_DeviceNum;       Make a GS/OS D_Info call to the next deviceGetDInfo	lda >D_DeviceNum	inc a	sta >D_DeviceNumGetDeviceInfo	jsl GSOS	dc.w D_Info	dc.l D_Info_Parms	bcc NoError;       If we got back an "InvalidDevNum" error, we're out of devices.@1	cmp #InvalidDevNum	bne GetDInfo;       If we've been through the whole device list, we're done.	lda Temp	; Restore the current device number	sta >D_DeviceNum	bra SearchDone;       Get the volume's name.NoError	lda outputPath	sta Vol_Name_Ptr	lda outputPath+2	sta Vol_Name_Ptr+2	jsl GSOS	dc.w Volume	dc.l Volume_Parms	bcc ResizeBuffer	cmp #BufferTooSmall	bne GetDInfo	; Got an error, try next deviceResizeBuffer	pha	; Room for result	pha	lda outputPath+2	; Pointer to GStr to resize	pha	lda outputPath	pha	jsl GStrResize	plx	stx outputPath	ply	sty outputPath+2	bcs NoError	; Try again if it didn't fit before;       Check the volume for root level scripts.	jsl AddScripts	; X & Y point to full pathname of directory	php	; save carry flag	pha	; save any error value	ldx outputPathHdl+2	; Reestablish the ptr in outputPath	lda outputPathHdl	;   (AddScripts may have moved it)	jsl DeRef	sta outputPath	stx outputPath+2	pla	; restore error value	plp	; restore carry flag;       Keep checking til all online volumes have been checked.	bcc GetDInfo	brl ErrorExit	Eject; Dispose of the pathname bufferSearchDone	lda outputPath+2	pha	lda outputPath	pha	jsl GStrDispose; Now check the message center and see if there were scripts to be "OPEN"ed.; If so, they must be added to the script lists no matter where they are; located and they will be the hilited scripts.	jsl CheckMsgCenter	bcs ErrorExit	sta MsgCenterStatus	; Save the non-error return status; We've got all the scripts we're going to get.  If our memory segment is; still empty, we didn't find any scripts at all!  Notify the user and we're; done...the Customized Installation dialog can't do anything without a script.	pha	pha	lda >ScriptFileHdl+2	pha	lda >ScriptFileHdl	pha	ldx #GetHandleSize	jsl ToolLocator	pla	sta TempA	pla	ora TempA	bne AlphabetizeList	lda #$0082	; Oops!  No scripts were found at all!	sec	bra ErrorExit; Alphabetize the list.AlphabetizeList	jsl Alphabetize	; sets <ScriptListPtr & >ScriptListSize; If there were no scripts to be "OPENed, set the flags byte on the first; member to $80 so it will be hilited.	lda MsgCenterStatus	; Recover the non-error return status	bmi CloseTheWindow	; If status = -1, don't hilite first	lda <ScriptListPtr	sta <ZPTemp	lda <ScriptListPtr+2	sta <ZPTemp+2	sep #$0020	LongA Off	ldy #0004	; Offset to member's flag byte	lda #$80	; Desired flag value	sta [<ZPTemp],y	; Store it.	LongA On	rep #$0020; Close the user notification box and we're done.CloseTheWindow	jsl CloseMsgWindow	clc	rtsErrorExit	pha	php	jsl CloseMsgWindow	plp	pla	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Local DataExpand_Parms	dc.w 0003	; pCount	dc.l inputPath	; inputPathoutputPath	dc.l 00000000	; outputPath	dc.w $8000	; flagsoutputPathHdl	ds.l 1	; handle to outputPath pointerinputPath	dc.w inputPathEnd-*-2	dc.b '9:SCRIPTS'inputPathEndMsgCenterStatus	ds.w 1Temp	ds.w 1	; Temporary local storageTempA	ds.w 1Volume_Parms	dc.w 0002	; Parameter countDev_Name_Ptr	dc.l Dev_Name+2	; Device name pointerVol_Name_Ptr	dc.l 00000000	; Volume name pointer	EndP	End